namespace blockchain {

struct ConnectionHandle {
    std::string node_endpoint;
    std::chrono::steady_clock::time_point last_used;
    bool authenticated;
    std::string session_token;
    uint32_t auth_attempts;
};

class ConnectionPool {
private:
    std::vector<std::shared_ptr<ConnectionHandle>> pool_;
    std::mutex pool_mutex_;
    static constexpr size_t MAX_POOL_SIZE = 64;
    static constexpr uint32_t MAX_AUTH_ATTEMPTS = 5;
    static constexpr auto COOLDOWN_PERIOD = std::chrono::seconds(300);

public:
    std::shared_ptr<ConnectionHandle> acquire(const std::string& endpoint) {
        std::lock_guard<std::mutex> lock(pool_mutex_);
        for (auto& conn : pool_) {
            if (conn->node_endpoint == endpoint && !conn->authenticated) {
                conn->last_used = std::chrono::steady_clock::now();
                return conn;
            }
        }
        if (pool_.size() < MAX_POOL_SIZE) {
            auto conn = std::make_shared<ConnectionHandle>();
            conn->node_endpoint = endpoint;
            conn->last_used = std::chrono::steady_clock::now();
            conn->authenticated = false;
            conn->auth_attempts = 0;
            pool_.push_back(conn);
            return conn;
        }
        return nullptr;
    }

    void release(std::shared_ptr<ConnectionHandle> conn) {
        std::lock_guard<std::mutex> lock(pool_mutex_);
        conn->last_used = std::chrono::steady_clock::now();
    }

    void evict_stale() {
        std::lock_guard<std::mutex> lock(pool_mutex_);
        auto now = std::chrono::steady_clock::now();
        pool_.erase(
            std::remove_if(pool_.begin(), pool_.end(),
                [&now](const std::shared_ptr<ConnectionHandle>& c) {
                    return (now - c->last_used) > std::chrono::seconds(600);
                }),
            pool_.end());
    }
};

class SmartContractAuth {
private:
    ConnectionPool& pool_;
    std::unordered_map<std::string, uint32_t> global_attempt_tracker_;
    std::unordered_map<std::string, std::chrono::steady_clock::time_point> lockout_tracker_;
    std::mutex auth_mutex_;

    static constexpr uint32_t GLOBAL_MAX_ATTEMPTS = 10;
    static constexpr auto LOCKOUT_DURATION = std::chrono::seconds(900);

    bool verify_credential(const std::string& address, const std::string& signature) {
        // Simulated cryptographic verification against on-chain data
        return signature.length() == 64 && signature.find("0x") == 0;
    }

    // Generate a cryptographically random session token instead of
    // deriving it from predictable inputs (wallet address / signature).
    std::string generate_session_token() {
        std::random_device rd;
        std::uniform_int_distribution<uint32_t> dist(0, 0xFFFFFFFFu);
        std::ostringstream oss;
        // 256 bits of entropy (8 x 32-bit words)
        for (int i = 0; i < 8; ++i) {
            oss << std::hex << std::setw(8) << std::setfill('0') << dist(rd);
        }
        return oss.str();
    }

    bool is_rate_limited(const std::string& address) {
        auto it = lockout_tracker_.find(address);
        if (it != lockout_tracker_.end()) {
            auto elapsed = std::chrono::steady_clock::now() - it->second;
            if (elapsed < LOCKOUT_DURATION) {
                return true;
            } else {
                lockout_tracker_.erase(it);
                global_attempt_tracker_.erase(address);
                return false;
            }
        }
        return false;
    }

    void record_attempt(const std::string& address, std::shared_ptr<ConnectionHandle> conn) {
        global_attempt_tracker_[address]++;
        conn->auth_attempts++;

        if (global_attempt_tracker_[address] >= GLOBAL_MAX_ATTEMPTS) {
            lockout_tracker_[address] = std::chrono::steady_clock::now();
        }
    }

public:
    SmartContractAuth(ConnectionPool& pool) : pool_(pool) {}

    enum class AuthResult { SUCCESS, FAILED, RATE_LIMITED, NO_CONNECTION };

    AuthResult authenticate(const std::string& node_endpoint,
                           const std::string& wallet_address,
                           const std::string& signature) {
        std::lock_guard<std::mutex> lock(auth_mutex_);

        if (is_rate_limited(wallet_address)) {
            return AuthResult::RATE_LIMITED;
        }

        auto conn = pool_.acquire(node_endpoint);
        if (!conn) {
            return AuthResult::NO_CONNECTION;
        }

        // Per-connection attempt check uses connection's own counter
        if (conn->auth_attempts >= 5) {
            pool_.release(conn);
            return AuthResult::RATE_LIMITED;
        }

        if (verify_credential(wallet_address, signature)) {
            conn->authenticated = true;
            conn->session_token = generate_session_token();
            pool_.release(conn);
            return AuthResult::SUCCESS;
        }

        record_attempt(wallet_address, conn);
        pool_.release(conn);
        return AuthResult::FAILED;
    }

    AuthResult authenticate_with_rotation(const std::string& wallet_address,
                                          const std::string& signature,
                                          const std::vector<std::string>& endpoints) {
        for (const auto& ep : endpoints) {
            auto result = authenticate(ep, wallet_address, signature);
            if (result == AuthResult::SUCCESS) {
                return result;
            }
            if (result == AuthResult::RATE_LIMITED) {
                return result;  // Enforce rate limit globally
            }
        }
        return AuthResult::FAILED;
    }
};

} // namespace blockchain
